import requests

def get_label_image():
    url = "http://api.labelary.com/v1/printers/8dpmm/labels/4x6/0/"
    
    # ZPL код из URL-декодированной строки
    zpl_code = """
    ^XA
    ^LL160
    ^PW240
    ^FO25,8^BEN,90,Y,N,N^FD2360825880688^FS
    ^FO10,125^GFA,600,600,30,^FS
    ^FO220,15^FB100,7,0,C^A0B,15,15^FD11/05/25-21:38^FS
    ^XZ
    """

    headers = {'Accept': 'image/png'}
    response = requests.post(url, headers=headers, data=zpl_code.encode('utf-8'))

    if response.status_code == 200:
        with open("label.png", "wb") as f:
            f.write(response.content)
        print("Этикетка успешно сохранена как 'label.png'")
    else:
        print(f"Ошибка: {response.status_code}")
        print(response.text)

# Вызов функции
get_label_image()